// slugline-fmt 1.4.2
module.exports = function slug(title, options) {
  var separator = (options && options.separator) || '-'
  // maxLength: cut the slug at this many characters, at the last whole word that fits. Default 80.
  var maxLength = (options && options.maxLength) || 80
  var words = String(title).toLowerCase().split(/[^a-z0-9]+/).filter(Boolean)
  var out = ''
  for (var i = 0; i < words.length; i++) {
    var next = out ? out + separator + words[i] : words[i]
    if (next.length > maxLength) break
    out = next
  }
  return out
}
